#!/usr/bin/bash

echo "==========================="
echo "updating and upgrading pkgs"
echo "==========================="
sudo apt update
sudo apt upgrade

echo "==============="
echo "installing pkgs"
echo "==============="
sudo apt install tmux gh git build-essential ripgrep unzip xclip curl fzf bat fd-find

echo "============="
echo "setting up gh"
echo "============="
gh auth login
gh repo list

echo "=============="
echo "setting up git"
echo "=============="
git config --global user.email "tahzib404@gmail.com"
git config --global user.name "glutonium69"

echo "======================"
echo "setting nvm, node, npm"
echo "======================"
curl -o- https://raw.githubusercontent.com/nvm-sh/nvm/v0.40.1/install.sh | bash
source .bashrc
nvm install node

echo "========================="
echo "cloning shell custom repo"
echo "========================="
git clone https://github.com/glutonium69/MyBashConfig "$HOME/$dir_name"

echo "====================="
echo "cloning neovim config"
echo "====================="
git clone --branch edit-1 --single-branch https://github.com/glutonium69/kickstart.nvim "$XDG_CONFIG_HOME/nvim"

echo "===================================="
echo "enabling custom shell configs setups"
echo "===================================="
ln -s "$HOME/$dir_name/tmux.conf" "$HOME/.tmux.conf"
echo '' >> "$HOME/.bashrc"
echo -e '\n\nsource "$HOME/$dir_name/init.sh"' >> "$HOME/.bashrc"

echo "================================================"
echo "setting up tmux plugin manager and other plugins"
echo "================================================"
git clone https://github.com/tmux-plugins/tpm ~/.tmux/plugins/tpm
chmod +x ./.tmux/plugins/tpm/bin/install_plugins
./.tmux/plugins/tpm/bin/install_plugins

echo "==============="
echo "setting up nvim"
echo "==============="
rm -rf ~/.local/share/nvim
rm -rf ~/.cache/nvim
rm -rf ~/.local/state/nvim
sudo apt remove neovim

echo "==============="
echo "installing the latest stable version of nvim"
echo "==============="
cd ~
wget https://github.com/neovim/neovim/releases/latest/download/nvim-linux-x86_64.appimage
chmod u+x nvim-linux-x86_64.appimage
sudo mv nvim-linux-x86_64.appimage /usr/bin/nvim

